$$
\begin{aligned}
\mathbf{a}\cdot(\mathbf{b}\times\mathbf{c})&=\begin{vmatrix}2&-2&k\\-2&-1&-2\\2&3&2\end{vmatrix}\\&=(2)\cdot \begin{vmatrix}-1&-2\\3&2\end{vmatrix}\\&\quad -(-2)\cdot \begin{vmatrix}-2&-2\\2&2\end{vmatrix}\\&\quad +(k)\cdot \begin{vmatrix}-2&-1\\2&3\end{vmatrix}\\&=(2)\cdot ((-1)\cdot (2)-(-2)\cdot (3))\\&\quad -(-2)\cdot ((-2)\cdot (2)-(-2)\cdot (2))\\&\quad +(k)\cdot ((-2)\cdot (3)-(-1)\cdot (2))\\&=(2)\cdot (4)\\&\quad -(-2)\cdot (0)\\&\quad +(k)\cdot (-4)\\&=8 - 4 k
